/* Imports: names the loader resolves in the runtime's table (Api.import gives the address at run time). */

/* The firmware's eMMC block read; 0 = ok. */
int32_t fw_block_read(uint32_t sector, uint32_t bytes, uint8_t *buf);

/* The firmware's operator new (the 32 MiB buddy allocator). */
uint8_t *fw_alloc(uint32_t size);

/* The firmware's free, paired with fw_alloc. */
void fw_free(uint8_t *p);

/* Press or release a panel key. Needs core/input: the import is not found without it. */
int32_t input_key(uint32_t code, uint32_t down);

/* Turn an encoder by `delta`. Needs core/input: the import is not found without it. */
int32_t input_turn(uint32_t encoder, int32_t delta);

/* Add the vendor bulk interface (interface 2, EP2 OUT and IN, 512-byte packets) to the USB MIDI configuration. In USB MIDI mode the device re-enumerates once; in another mode only the configuration is prepared, and the next switch to USB MIDI (usb_bulk_takeover, or the user's menu) enumerates with the interface in place. `io_id` is the I/O job that usb_bulk_* wakes when a receive buffer is full. Call it until it returns 0: the same job may call again. Another job gets E_BUSY (one owner). Task context. 0, or a negative error (E_STATE: the device is not in USB MIDI mode (USB CONFIG), or a mode switch is settling (about a second); call again later, E_CONTRACT: the firmware's USB tables are not the stock ones, E_NOMEM: no free slot on the runtime's per-pass list). See <dk/platform/usb_bulk.h>. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_enable(int32_t io_id);

/* The job that called usb_bulk_enable goes away (call it in dkm_fini): the adapter stops waking it and another job may enable the interface. The interface stays in the USB configuration until the next boot. 0, or E_STATE for another job. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_disable(int32_t io_id);

/* The next full receive buffer, in arrival order: 1 and `*buf`, `*len` set (the buffer is yours until usb_bulk_release), or 0 when none is full. Never blocks. A buffer holds the bytes of one USB transfer: up to 16 KiB, ended by a short packet or a full buffer, so a message of a multiple of 512 bytes must be followed by a zero-length packet from the host. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_take(uint8_t **buf, uint32_t *len);

/* Give a buffer from usb_bulk_take back: it is queued for the next transfer. 0, or E_STATE for a pointer that is not a taken buffer. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_release(uint8_t *buf);

/* Send `len` bytes (1 to 16384) to the host on EP2 IN. The bytes are copied: `buf` is free when the call returns. 0, E_BUSY when both send slots are in flight (the job is woken when one completes), E_AGAIN (-72) when nothing is in flight and the engine refused the transfer (the job is woken within a few milliseconds to try again), E_STATE when the host is not connected or the bus was reset during the call, E_LENGTH. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_send(const uint8_t *buf, uint32_t len);

/* State word: bit 0 enabled, bit 1 connected (the host configured interface 2), bit 2 wrong mode (the device is not in USB MIDI mode; read live), bit 3 taken over (usb_bulk_takeover is active), bits 8..15 receive buffers full, bits 16..23 send slots in flight, bits 24..31 the reset count (it changes when the USB bus is reset or the host disconnects; a transfer in progress is void then). Needs core/usb-bulk: the import is not found without it. */
uint32_t usb_bulk_state(void);

/* Set the one per-block callback of core/dsp-link (0: off): `void cb(const volatile u16 *rec)`, called every block in the block interrupt with the copy of the previous DSP reply record. Keep it short: a plain C function, no allocation, no logging. Clear it in `fini`. Without core/dsp-link the call does nothing. Needs core/dsp-link: the import is not found without it. */
void dl_set_tick_cb(uint8_t *cb);

/* The 1500 Hz block clock, for a module that wants to measure time. */
uint32_t dkrt_blocks(void);

/* Set (or, with 0, clear) the one log sink and its tick: `void sink(const dk_log_ev *e)` receives every event the runtime logs, before any filter, in whatever task logs, with interrupts masked (short, no waiting, no logging). `dk_log_ev` is 32 bytes: `u32 seq` (0 here), `u32 time` (block counter), `u16 kind`, `u16 flags`, `u32 a[5]`. At the call the sink gets the events of the runtime's small ring (the boot and the errors so far), oldest first. `tick` (0: none) is `void tick(void)`, called once per pass of the UI task with this module as the source, outside the interrupt mask: it keeps the module off slot 0, which only one module can hold. The runtime clears a sink or a tick that points into a module's memory after its `fini`. Used by digikit/debug. */
void dkrt_log_sink_set(uint8_t *sink, uint8_t *tick);

/* Log one event as the runtime's own call does (the sink and the small ring see it): `kind` and `flags` as in `dk_log_ev`, `a` five words. The source is the module that is running unless `flags` holds one. For a module that logs a kind of its own. */
void dkrt_log_ev(uint32_t kind, uint32_t flags, const uint32_t *a);

/* The RAM ranges `[lo, hi)` of the device file's `[digikit] peek`: returns how many there are, and for `i` below that writes `lo, hi` to `out[0..2]`. For a module that implements PEEK. */
uint32_t dkrt_peek_range(uint32_t i, uint32_t *out);

/* The machine type of track 0 to 15 of the active kit, read from the firmware (read-only); -1 for a track the firmware has no type for, -2 when there is no project yet. */
int32_t dkrt_track_type(uint32_t track);

/* The selected track and its Sound parameter words (read-only, from the firmware's own accessors). Writes the first `n` s16 words of that track's Sound array to `out` (words past the device's count are 0) and returns the track, 0 to 15. Returns -2 when there is no project yet and -3 when the track has no Sound record (a kit is loading): `out` is not written then. The index of a word is the mirror index of the firmware's parameter table, not a parameter code. Used by digikit/debug. */
int32_t dkrt_selected_params(int16_t *out, uint32_t n);

/* Take the USB port over for the bulk link, or renew a take-over (call it again at least every 20 s while the host works: any bulk transfer counts too). In USB AUDIO/MIDI the adapter switches the device to USB MIDI in RAM about 50 ms later, from its tick (USB audio pauses; the USB CONFIG setting is not written, so a reboot returns to it); in USB MIDI it succeeds at once without a switch. 0, E_STATE in Overbridge or another USB mode, E_NOMEM (no free slot on the runtime's per-pass list). Callable from a command handler: it only records the request. Then call usb_bulk_enable until it stops returning E_STATE. The adapter gives back by itself after the host's disconnect or suspend, after 30 s without host activity, and drops the take-over when the USB mode changes by another route (the user's menu choice wins). See <dk/platform/usb_bulk.h>. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_takeover(void);

/* End a take-over: about 50 ms later the adapter switches back to the USB mode the device had. 0, also when nothing is taken over. Callable from a command handler. Needs core/usb-bulk: the import is not found without it. */
int32_t usb_bulk_giveback(void);

/* Entry points of a .dkm (symbols of its object). */

/* Runs once after the copy, relocation and cache flush. Returns 0 = ok; the module is unloaded otherwise. */
int32_t dkm_init(const dk_api *api);

/* Runs when the module is unloaded. */
void dkm_fini(const dk_api *api);

/* Optional: the module's settings. Runs when the user opens the module's SETTINGS... in the DIGIKIT menu, and adds the rows of a menu (core/ui must be in the image). The prototype is in <dk/platform/ui.h> (`DK_MENU(fill)` defines it): `void dkm_menu(dk_ui_menu *m, void *ctx)`. */

/* Slots: function pointers the firmware hooks call. A module binds one by exporting dkm_slot_<n>. Slot 0 runs once per pass of the UI task's event loop (about 120 Hz). */
void dkm_slot_0(const dk_api *api);
void dkm_slot_1(const dk_api *api);
void dkm_slot_2(const dk_api *api);
void dkm_slot_3(const dk_api *api);
void dkm_slot_4(const dk_api *api);
void dkm_slot_5(const dk_api *api);
void dkm_slot_6(const dk_api *api);
void dkm_slot_7(const dk_api *api);

#define DK_API_MINOR 11

#endif /* DK_GEN_API_H */
